import { cookies, headers } from 'next/headers'

function preferredLanguage(acceptLanguage: string | null): string {
  if (!acceptLanguage) {
    return 'unknown'
  }

  const candidates = acceptLanguage
    .split(',')
    .map((part) => {
      const [rawTag, ...params] = part.trim().split(';')
      const tag = rawTag.trim()
      const qualityParam = params.find((param) =>
        param.trim().toLowerCase().startsWith('q=')
      )
      const quality = qualityParam
        ? Number.parseFloat(qualityParam.trim().slice(2))
        : 1

      return {
        tag,
        quality: Number.isFinite(quality) ? quality : 0,
      }
    })
    .filter((candidate) => candidate.tag.length > 0)
    .sort((left, right) => right.quality - left.quality)

  return candidates[0]?.tag ?? 'unknown'
}

export default async function Home() {
  const cookieStore = await cookies()
  const theme = cookieStore.get('theme')?.value ?? 'light'
  const language = preferredLanguage(
    (await headers()).get('accept-language')
  )

  return (
    <main>
      <h1>User Preferences</h1>
      <p>Theme: {theme}</p>
      <p>Preferred language: {language}</p>
    </main>
  )
}

